/**
 * Generates `supabase/functions/_shared/nutrient-map.generated.ts`: a
 * self-contained (dependency-free) lookup built from the canonical nutrient
 * catalog in `packages/core/src/nutrients.ts`.
 *
 * Supabase Edge Functions run on Deno and cannot import workspace packages
 * (`@ration/core`), so the parts of the catalog the functions need are copied
 * into a generated file that IS committed. Re-run after changing the catalog:
 *
 *   node --import tsx packages/core/scripts/generate-edge-nutrient-map.ts
 *   node --import tsx packages/core/scripts/generate-edge-nutrient-map.ts --check   # exit 1 when stale
 *
 * (`node --import tsx`, not the `tsx` CLI: the CLI opens a unix socket.)
 * A db-tests test also fails when the committed file is stale.
 *
 * Contents of the generated file:
 *   CATALOG_UNITS       code -> catalog unit
 *   NON_COMPUTED_CODES  catalog codes that sources may provide (basis of `completeness`)
 *   FDC_NUTRIENT_MAP    FDC nutrient id -> { code, unit, fdcUnit, factor, rank }
 *                       amount_in_catalog_unit = fdc_amount * factor   (when the FDC unit is `fdcUnit`)
 *                       rank: lower wins when several ids describe one code
 *                       (canonical id 0, alternates 1.. highest id first, converted ids 10+)
 *   OFF_NUTRIENT_MAP    Open Food Facts `nutriments` key (no `_100g` suffix) -> { code, unit, factor }
 *                       amount_in_catalog_unit = off_value * factor. OFF reports everything except
 *                       energy-kcal in GRAMS per 100 g, so g -> mg is x1000 and g -> ug is x1e6.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { FDC_CONVERTED_IDS, NUTRIENTS } from '../src/nutrients';

const here = dirname(fileURLToPath(import.meta.url));

/** Default output path (repo root / supabase / functions / _shared). */
export const OUTPUT_PATH = resolve(
  here,
  '../../../supabase/functions/_shared/nutrient-map.generated.ts',
);

/** OFF grams -> catalog unit. */
const OFF_FACTOR_BY_UNIT: Readonly<Record<string, number>> = {
  kcal: 1, // energy-kcal_100g is already kcal
  g: 1,
  mg: 1000,
  ug: 1_000_000,
};

/**
 * Per-code OFF factor overrides.
 *  ALCOHOL_G: OFF `alcohol_100g` is "% vol" (ml ethanol per 100 ml), NOT grams.
 *  Ethanol weighs 0.789 g/ml, and OFF treats 1 ml ~ 1 g for drinks, so the
 *  catalog amount (g per 100 g) is value * 0.789.
 */
const OFF_FACTOR_OVERRIDES: Readonly<Record<string, number>> = {
  ALCOHOL_G: 0.789,
};

const FDC_UNIT_BY_CATALOG_UNIT: Readonly<Record<string, string>> = {
  kcal: 'KCAL',
  g: 'G',
  mg: 'MG',
  ug: 'UG',
  iu: 'IU',
  ml: 'ML',
};

/** JS number literal that round-trips (avoids 0.23900000000000002 noise). */
function num(n: number): string {
  return String(Number(n.toPrecision(12)));
}

const q = (s: string): string => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

export function renderNutrientMap(): string {
  const lines: string[] = [];
  const push = (s = ''): void => {
    lines.push(s);
  };

  push(
    '// GENERATED by packages/core/scripts/generate-edge-nutrient-map.ts - do not edit by hand.',
  );
  push('// Regenerate: node --import tsx packages/core/scripts/generate-edge-nutrient-map.ts');
  push('//');
  push(
    '// Self-contained copy of the parts of the canonical nutrient catalog (packages/core/src/nutrients.ts)',
  );
  push('// that the Edge Functions need. Edge code cannot import workspace packages.');
  push('');
  push("export type CatalogUnit = 'kcal' | 'g' | 'mg' | 'ug' | 'iu' | 'ml';");
  push('');
  push('export interface FdcNutrientEntry {');
  push('  /** Catalog nutrient code (foods.nutrients key). */');
  push('  code: string;');
  push('  /** Catalog unit of `code`. */');
  push('  unit: CatalogUnit;');
  push('  /** Unit (upper case, as in FDC `unitName`) in which FDC reports this nutrient id. */');
  push('  fdcUnit: string;');
  push('  /** catalog amount = FDC amount * factor (valid when the FDC unit is `fdcUnit`). */');
  push('  factor: number;');
  push('  /** Lower wins when several FDC ids describe the same code. */');
  push('  rank: number;');
  push('}');
  push('');
  push('export interface OffNutrientEntry {');
  push('  code: string;');
  push('  unit: CatalogUnit;');
  push('  /** catalog amount = OFF `<key>_100g` value * factor (OFF reports grams per 100 g). */');
  push('  factor: number;');
  push('}');
  push('');

  // CATALOG_UNITS
  push('/** Every catalog code (display order) -> its unit. */');
  push('// prettier-ignore');
  push('export const CATALOG_UNITS: Readonly<Record<string, CatalogUnit>> = {');
  for (const n of NUTRIENTS) push(`  ${n.code}: ${q(n.unit)},`);
  push('};');
  push('');

  // NON_COMPUTED_CODES
  const nonComputed = NUTRIENTS.filter((n) => !n.computed);
  push('/** Codes a source may provide (computed ones such as NET_CARBS_G are excluded). */');
  push('// prettier-ignore');
  push('export const NON_COMPUTED_CODES: readonly string[] = [');
  for (const n of nonComputed) push(`  ${q(n.code)},`);
  push('];');
  push('');
  push('/** Codes derived from other nutrients; never stored from a source. */');
  push('// prettier-ignore');
  push('export const COMPUTED_CODES: readonly string[] = [');
  for (const n of NUTRIENTS.filter((x) => x.computed)) push(`  ${q(n.code)},`);
  push('];');
  push('');

  // FDC map
  interface FdcRow {
    id: number;
    code: string;
    unit: string;
    fdcUnit: string;
    factor: number;
    rank: number;
  }
  const fdcRows: FdcRow[] = [];
  for (const n of nonComputed) {
    const fdcUnit = FDC_UNIT_BY_CATALOG_UNIT[n.unit];
    if (!fdcUnit) throw new Error(`no FDC unit for catalog unit ${n.unit} (${n.code})`);
    if (n.fdcId !== null) {
      fdcRows.push({ id: n.fdcId, code: n.code, unit: n.unit, fdcUnit, factor: 1, rank: 0 });
    }
    // alternates: highest id first (e.g. ENERGY 1008, then 2048 Atwater specific, then 2047 general)
    const alts = [...(n.fdcAltIds ?? [])].sort((a, b) => b - a);
    alts.forEach((id, i) => {
      fdcRows.push({ id, code: n.code, unit: n.unit, fdcUnit, factor: 1, rank: i + 1 });
    });
  }
  // converted ids (different FDC unit)
  const converted = [...FDC_CONVERTED_IDS.entries()].sort((a, b) => a[0] - b[0]);
  converted.forEach(([id, { code, factor }], i) => {
    const entry = NUTRIENTS.find((n) => n.code === code);
    if (!entry) throw new Error(`FDC_CONVERTED_IDS references unknown code ${code}`);
    const fdcUnit = id === 1062 ? 'KJ' : id === 1110 ? 'IU' : null;
    if (!fdcUnit) throw new Error(`unknown FDC unit for converted id ${id}: extend the generator`);
    fdcRows.push({ id, code, unit: entry.unit, fdcUnit, factor, rank: 10 + i });
  });
  const seenIds = new Set<number>();
  for (const r of fdcRows) {
    if (seenIds.has(r.id)) throw new Error(`FDC id ${r.id} maps to more than one nutrient`);
    seenIds.add(r.id);
  }
  fdcRows.sort((a, b) => a.id - b.id);

  push('/**');
  push(' * FDC nutrient id -> catalog nutrient. Ids 1062 (kJ) and 1110 (IU) are converted; the');
  push(' * others are in the catalog unit. Use `rank` to pick one value per code.');
  push(' */');
  push('// prettier-ignore');
  push('export const FDC_NUTRIENT_MAP: Readonly<Record<number, FdcNutrientEntry>> = {');
  for (const r of fdcRows) {
    push(
      `  ${r.id}: { code: ${q(r.code)}, unit: ${q(r.unit)}, fdcUnit: ${q(r.fdcUnit)}, factor: ${num(r.factor)}, rank: ${r.rank} },`,
    );
  }
  push('};');
  push('');

  // OFF map
  push('/**');
  push(' * Open Food Facts `nutriments` key (without the `_100g` suffix) -> catalog nutrient.');
  push(' * OFF reports grams per 100 g (energy-kcal: kcal), so mg x1000 and ug x1e6.');
  push(' * ALCOHOL_G: OFF `alcohol` is % vol, converted with the ethanol density 0.789 g/ml.');
  push(
    ' * Salt is not a catalog nutrient: off-product.ts derives SODIUM_MG from `salt` when `sodium` is absent.',
  );
  push(' */');
  push('// prettier-ignore');
  push('export const OFF_NUTRIENT_MAP: Readonly<Record<string, OffNutrientEntry>> = {');
  const seenKeys = new Set<string>();
  for (const n of nonComputed) {
    if (!n.offKey) continue;
    if (seenKeys.has(n.offKey))
      throw new Error(`OFF key ${n.offKey} maps to more than one nutrient`);
    seenKeys.add(n.offKey);
    const factor = OFF_FACTOR_OVERRIDES[n.code] ?? OFF_FACTOR_BY_UNIT[n.unit];
    if (factor === undefined) {
      throw new Error(`no OFF factor for unit ${n.unit} (${n.code}): extend the generator`);
    }
    push(`  ${q(n.offKey)}: { code: ${q(n.code)}, unit: ${q(n.unit)}, factor: ${num(factor)} },`);
  }
  push('};');
  push('');

  return lines.join('\n');
}

function main(argv: readonly string[]): void {
  const out = renderNutrientMap();
  if (argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(OUTPUT_PATH, 'utf8');
    } catch {
      // missing file counts as stale
    }
    if (current !== out) {
      process.stderr.write(`${OUTPUT_PATH} is stale: re-run the generator\n`);
      process.exit(1);
    }
    process.stderr.write('nutrient-map.generated.ts is up to date\n');
    return;
  }
  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  writeFileSync(OUTPUT_PATH, out, 'utf8');
  process.stderr.write(`wrote ${OUTPUT_PATH}\n`);
}

// Run only when executed directly (the db-tests staleness check imports this file).
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2));
}
